// STØMP — kick synth panel for [jsui] (mgraphics, ES5). One panel in Live's device strip (1100×169).
// The knobs here are only a face: every value lives in a hidden live.dial (Live parameter: automation,
// presets, Push). Dragging sends "<name> <value>" to it; it sends "p <name> <value>" back.
// From the patch: "note <pitch> <velocity>" (MIDI in), "level <L> <R>" (output peaks), "sr <rate>".
// To the patch besides parameters: "knote <n>", "kvel <v>", "hit" (the PLAY pad).
// ASCII text only; the Ø of the logo is drawn as geometry.

mgraphics.init();
mgraphics.relative_coords = 0;
mgraphics.autofill = 0;
inlets = 1;
outlets = 1;

// <SPEC> generated by tools/make_engine.py from tools/spec.py — do not edit by hand
var SPEC_KNOBS = [{"n": "amp_len", "sec": "AMP", "lab": "LENGTH", "d": 0.52}, {"n": "amp_att", "sec": "AMP", "lab": "ATTACK", "d": 0.0}, {"n": "amp_crv", "sec": "AMP", "lab": "CURVE", "d": 0.38}, {"n": "pit_swp", "sec": "PITCH", "lab": "SWEEP", "d": 0.55}, {"n": "pit_time", "sec": "PITCH", "lab": "TIME", "d": 0.42}, {"n": "pit_crv", "sec": "PITCH", "lab": "CURVE", "d": 0.62}, {"n": "clk_amt", "sec": "CLICK", "lab": "CLICK", "d": 0.35}, {"n": "clk_tone", "sec": "CLICK", "lab": "TONE", "d": 0.45}, {"n": "nz_amt", "sec": "NOISE", "lab": "NOISE", "d": 0.12}, {"n": "nz_col", "sec": "NOISE", "lab": "COLOR", "d": 0.55}, {"n": "nz_dec", "sec": "NOISE", "lab": "DECAY", "d": 0.25}, {"n": "hm_amt", "sec": "HARM", "lab": "PARTIALS", "d": 0.15}, {"n": "hm_spr", "sec": "HARM", "lab": "SPREAD", "d": 0.0}, {"n": "dr_amt", "sec": "DRIVE", "lab": "DRIVE", "d": 0.35}, {"n": "dr_knee", "sec": "DRIVE", "lab": "HARD", "d": 0.25}, {"n": "fm_amt", "sec": "FM", "lab": "FM", "d": 0.08}, {"n": "fm_rat", "sec": "FM", "lab": "RATIO", "d": 0.2}, {"n": "fm_dec", "sec": "FM", "lab": "DECAY", "d": 0.35}, {"n": "wd_amt", "sec": "STEREO", "lab": "WIDTH", "d": 0.0}, {"n": "sp_amt", "sec": "STEREO", "lab": "SPACE", "d": 0.0}, {"n": "sp_time", "sec": "STEREO", "lab": "SIZE", "d": 0.35}, {"n": "level", "sec": "OUT", "lab": "LEVEL", "d": 0.75}, {"n": "tune", "sec": "OUT", "lab": "TUNE", "d": 0.5}];
var SPEC_SOURCES = [{"n": "vel_amt", "lab": "VELOCITY", "d": 0.5}, {"n": "rnd_amt", "lab": "RANDOM", "d": 0.5}];
var SPEC_DEPTHS = {"v_amp_len": 0, "v_amp_att": 0, "v_amp_crv": 0, "v_pit_swp": 0, "v_pit_time": 0, "v_pit_crv": 0, "v_clk_amt": 0.6, "v_clk_tone": 0, "v_nz_amt": 0, "v_nz_col": 0, "v_nz_dec": 0, "v_hm_amt": 0, "v_hm_spr": 0, "v_dr_amt": 0.3, "v_dr_knee": 0, "v_fm_amt": 0, "v_fm_rat": 0, "v_fm_dec": 0, "v_wd_amt": 0, "v_sp_amt": 0, "v_sp_time": 0, "v_level": 1.0, "v_tune": 0, "r_amp_len": 0, "r_amp_att": 0, "r_amp_crv": 0, "r_pit_swp": 0.1, "r_pit_time": 0, "r_pit_crv": 0, "r_clk_amt": 0, "r_clk_tone": 0.3, "r_nz_amt": 0, "r_nz_col": 0.3, "r_nz_dec": 0, "r_hm_amt": 0, "r_hm_spr": 0, "r_dr_amt": 0, "r_dr_knee": 0, "r_fm_amt": 0, "r_fm_rat": 0, "r_fm_dec": 0, "r_wd_amt": 0, "r_sp_amt": 0, "r_sp_time": 0, "r_level": 0, "r_tune": 0};
// </SPEC>

var W0 = 1100, H0 = 169;
var C = { bg: [0.105, 0.105, 0.105, 1], panel: [0.155, 0.155, 0.155, 1], ink: [0.84, 0.84, 0.84, 1], mid: [0.56, 0.56, 0.56, 1],
  dim: [0.40, 0.40, 0.40, 1], line: [0.30, 0.30, 0.30, 1], accent: [0.36, 0.82, 0.84, 1], pink: [0.95, 0.50, 0.66, 1], screen: [0.075, 0.075, 0.08, 1] };
var SRC = [{ pre: "v_", amt: "vel_amt", lab: "VELOCITY", short: "VEL", col: C.accent }, { pre: "r_", amt: "rnd_amt", lab: "RANDOM", short: "RND", col: C.pink }];

var P = {};
(function () {
  var i;
  for (i = 0; i < SPEC_KNOBS.length; i++) P[SPEC_KNOBS[i].n] = { v: SPEC_KNOBS[i].d, d: SPEC_KNOBS[i].d };
  for (i = 0; i < SPEC_SOURCES.length; i++) P[SPEC_SOURCES[i].n] = { v: SPEC_SOURCES[i].d, d: SPEC_SOURCES[i].d };
  for (var k in SPEC_DEPTHS) P[k] = { v: SPEC_DEPTHS[k], d: SPEC_DEPTHS[k], lo: -1, hi: 1 };
})();
function label(n) { for (var i = 0; i < SPEC_KNOBS.length; i++) if (SPEC_KNOBS[i].n === n) return SPEC_KNOBS[i].lab; return n; }

// columns: title, x, width, big knob, small knobs
var COLS = [
  { t: "AMP", x: 96, w: 88, big: "amp_len", sm: ["amp_att", "amp_crv"] },
  { t: "PITCH", x: 188, w: 88, big: "pit_swp", sm: ["pit_time", "pit_crv"] },
  { t: "CLICK", x: 494, w: 62, big: "clk_amt", sm: ["clk_tone"] },
  { t: "NOISE", x: 560, w: 88, big: "nz_amt", sm: ["nz_col", "nz_dec"] },
  { t: "HARM", x: 652, w: 62, big: "hm_amt", sm: ["hm_spr"] },
  { t: "DRIVE", x: 718, w: 62, big: "dr_amt", sm: ["dr_knee"] },
  { t: "FM", x: 784, w: 88, big: "fm_amt", sm: ["fm_rat", "fm_dec"] },
  { t: "STEREO", x: 876, w: 88, big: "wd_amt", sm: ["sp_amt", "sp_time"] },
  { t: "OUT", x: 968, w: 60, big: "level", sm: ["tune"] }
];
var DX = 280, DY = 6, DW = 210, DH = 157;          // the display
var SX = 1034;                                        // sources column
var KNOB_POS = {};                                    // name → [cx, cy, r] (for cables)

// ---------- the same maps as the engine (gen/voice.part.genexpr) ----------
function pw2(x) { return Math.pow(2, x); }
// Max's [jsui] runs old JavaScript (ES5): no Math.tanh / Math.log10 / Math.sign — own versions here.
// (v0.1.0 used Math.tanh in the display: paint stopped there, so the screen, VEL/RND, PATCH and the
// cables were never drawn in Live.)
function tanh(x) { if (x > 20) return 1; if (x < -20) return -1; var e = Math.exp(2 * x); return (e - 1) / (e + 1); }
function shapep(v) { return pw2((0.5 - v) * 6); }
var M = {
  alen: function (v) { return 0.05 * pw2(v * 5.32); }, aatt: function (v) { return 0.03 * v * v; },
  ptim: function (v) { return 0.005 * pw2(v * 6); }, swp: function (v) { return v * 72; },
  ctone: function (v) { return 1500 * pw2(v * 3); }, ncol: function (v) { return 200 * pw2(v * 6.3); },
  ndec: function (v) { return 0.01 * pw2(v * 6.3); }, fmr: function (v) { return 0.5 + v * 7.5; },
  fdec: function (v) { return 0.005 * pw2(v * 6); }, db: function (v) { return -30 + 36 * v; }, tune: function (v) { return (v - 0.5) * 48; }
};
function fnote(note) { return 440 * pw2((note - 69 + M.tune(P.tune.v)) / 12); }
// envelope and pitch of a hit at t seconds (knobs as they are, full velocity, no random)
function model(t, note) {
  var alen = M.alen(P.amp_len.v), aatt = M.aatt(P.amp_att.v);
  var ax = Math.max(0, Math.min(1, (t - aatt) / alen));
  var env = (aatt > 0.00002 ? Math.min(1, t / aatt) : 1) * Math.pow(1 - ax, shapep(P.amp_crv.v)) * Math.min(1, (1 - ax) * alen / 0.003);
  var pe = Math.pow(1 - Math.min(t / M.ptim(P.pit_time.v), 1), shapep(P.pit_crv.v));
  return { env: env, f: fnote(note) * pw2(M.swp(P.pit_swp.v) * pe / 12) };
}

function pct(v) { return Math.round(v * 100) + "%"; }
function fmtMs(s) { var ms = s * 1000; return ms >= 1000 ? (Math.round(ms / 10) / 100) + " s" : ms < 10 ? (Math.round(ms * 10) / 10) + " ms" : Math.round(ms) + " ms"; }
function fmtHz(hz) { return hz >= 1000 ? (Math.round(hz / 100) / 10) + " kHz" : Math.round(hz) + " Hz"; }
function sgn(x) { return (x > 0 ? "+" : "") + x; }
function valueText(n) {
  var v = P[n].v;
  switch (n) {
    case "amp_len": return fmtMs(M.alen(v));
    case "amp_att": return fmtMs(M.aatt(v));
    case "pit_swp": return "+" + Math.round(M.swp(v)) + " st";
    case "pit_time": return fmtMs(M.ptim(v));
    case "clk_tone": return fmtHz(M.ctone(v));
    case "nz_col": return fmtHz(M.ncol(v));
    case "nz_dec": return fmtMs(M.ndec(v));
    case "fm_rat": return "x" + (Math.round(M.fmr(v) * 100) / 100);
    case "fm_dec": return fmtMs(M.fdec(v));
    case "level": return sgn(Math.round(M.db(v) * 10) / 10) + " dB";
    case "tune": return sgn(Math.round(M.tune(v))) + " st";
  }
  return pct(v);
}

// ---------- state ----------
var hits = [], drag = null, dirty = true, scaleF = 1, hover = null;
var patchMode = false, selSrc = 0;
var lastNote = 36, lastVel = 1, hitT = -1;
var levL = 0, levR = 0;
var now = function () { return new Date().getTime(); };
function p(name, v) { if (P[name]) { P[name].v = +v; dirty = true; } }
function noteName(n) { var nm = ["C", "C#", "D", "D#", "E", "F", "F#", "G", "G#", "A", "A#", "B"]; return nm[((n % 12) + 12) % 12] + (Math.floor(n / 12) - 2); }
// "note <pitch> <velocity>" — MIDI from this track (note-ons only)
function note(pitch, vel) { if (+vel > 0) { lastNote = +pitch; lastVel = +vel / 127; hitT = now(); dirty = true; } }
function level(l, r) { levL = +l; levR = +r; dirty = true; }
function sr() { }
function send(name, v) { outlet(0, name, v); }
function play() { send("knote", lastNote); send("kvel", 1); outlet(0, "hit"); lastVel = 1; hitT = now(); dirty = true; }

var frame = new Task(function () {
  if (dirty || (hitT > 0 && now() - hitT < 2500)) { dirty = false; mgraphics.redraw(); }
}, this);
frame.interval = 33;
frame.repeat();
function notifydeleted() { frame.cancel(); }

// ---------- presets (panel only: they set the knobs) and DICE ----------
var PRESETS = [
  ["PUNCH", {}],
  ["BOOM 808", { amp_len: 0.78, amp_crv: 0.62, pit_swp: 0.33, pit_time: 0.55, pit_crv: 0.5, clk_amt: 0.12, nz_amt: 0.04, hm_amt: 0.06, dr_amt: 0.18, dr_knee: 0.1, fm_amt: 0 }],
  ["TECHNO", { amp_len: 0.56, amp_crv: 0.42, pit_swp: 0.6, pit_time: 0.38, pit_crv: 0.66, clk_amt: 0.45, clk_tone: 0.55, nz_amt: 0.15, hm_amt: 0.2, dr_amt: 0.55, dr_knee: 0.35 }],
  ["HARD", { amp_len: 0.5, amp_crv: 0.4, pit_swp: 0.75, pit_time: 0.34, pit_crv: 0.76, clk_amt: 0.6, clk_tone: 0.7, nz_amt: 0.2, nz_col: 0.7, dr_amt: 0.85, dr_knee: 0.7, fm_amt: 0.25, fm_rat: 0.2, level: 0.7 }],
  ["DEEP", { amp_len: 0.68, amp_crv: 0.5, pit_swp: 0.4, pit_time: 0.55, pit_crv: 0.45, clk_amt: 0.18, clk_tone: 0.3, nz_amt: 0.1, nz_col: 0.35, nz_dec: 0.45, hm_amt: 0.1, dr_amt: 0.25 }],
  ["TIGHT", { amp_len: 0.34, amp_crv: 0.25, pit_swp: 0.6, pit_time: 0.3, pit_crv: 0.72, clk_amt: 0.5, clk_tone: 0.6, nz_amt: 0.1, dr_amt: 0.4 }]
];
var preset = 0, presetName = "PUNCH";
function applySet(set) {
  for (var i = 0; i < SPEC_KNOBS.length; i++) {
    var n = SPEC_KNOBS[i].n, v = set.hasOwnProperty(n) ? set[n] : SPEC_KNOBS[i].d;
    send(n, Math.round(v * 1000) / 1000);
  }
}
function loadPreset(i) { preset = (i + PRESETS.length) % PRESETS.length; presetName = PRESETS[preset][0]; applySet(PRESETS[preset][1]); dirty = true; }
function rr(a, b) { return a + Math.random() * (b - a); }
// DICE: a new kick inside ranges that always give a usable, punchy kick
function dice() {
  applySet({ amp_len: rr(0.35, 0.75), amp_att: rr(0, 0.15), amp_crv: rr(0.25, 0.65), pit_swp: rr(0.3, 0.8), pit_time: rr(0.28, 0.6),
    pit_crv: rr(0.45, 0.8), clk_amt: rr(0.1, 0.65), clk_tone: rr(0.2, 0.8), nz_amt: rr(0, 0.25), nz_col: rr(0.3, 0.8), nz_dec: rr(0.1, 0.45),
    hm_amt: rr(0, 0.35), hm_spr: Math.random() < 0.7 ? 0 : rr(0, 0.6), dr_amt: rr(0.15, 0.85), dr_knee: rr(0, 0.8),
    fm_amt: Math.random() < 0.5 ? 0 : rr(0, 0.35), fm_rat: rr(0, 0.5), fm_dec: rr(0.1, 0.6),
    // DICE keeps the kick as dry and wide as you set it (WIDTH / SPACE / SIZE), and LEVEL / TUNE
    wd_amt: P.wd_amt.v, sp_amt: P.sp_amt.v, sp_time: P.sp_time.v, level: P.level.v, tune: P.tune.v });
  presetName = "DICE"; dirty = true;
}

// ---------- drawing ----------
function col(c, a) { mgraphics.set_source_rgba(c[0], c[1], c[2], a === undefined ? c[3] : a); }
function rect(x, y, w, h, c, fill, lw, a) {
  col(c, a); mgraphics.set_line_width(lw || 1);
  if (fill) { mgraphics.rectangle(x, y, w, h); mgraphics.fill(); } else { mgraphics.rectangle(x + 0.5, y + 0.5, w - 1, h - 1); mgraphics.stroke(); }
}
function font(s, b) { mgraphics.select_font_face(b ? "Ableton Sans Bold" : "Ableton Sans Medium"); mgraphics.set_font_size(s); }
function text(s, x, y, size, c, b) { font(size, b); col(c); mgraphics.move_to(x, y); mgraphics.show_text(s); }
function tw(s, size, b) { font(size, b); return mgraphics.text_measure(s)[0]; }
function textC(s, cx, y, size, c, b) { text(s, cx - tw(s, size, b) / 2, y, size, c, b); }
function textR(s, rx, y, size, c, b) { text(s, rx - tw(s, size, b), y, size, c, b); }
function line(x1, y1, x2, y2, c, lw, a) { col(c, a); mgraphics.set_line_width(lw || 1); mgraphics.move_to(x1, y1); mgraphics.line_to(x2, y2); mgraphics.stroke(); }
function circle(cx, cy, r, c, fill, lw, a) { col(c, a); mgraphics.set_line_width(lw || 1); mgraphics.ellipse(cx - r, cy - r, 2 * r, 2 * r); if (fill) mgraphics.fill(); else mgraphics.stroke(); }
function arc(cx, cy, r, a0, a1, c, lw, a) {
  col(c, a); mgraphics.set_line_width(lw || 1);
  var n = Math.max(2, Math.ceil(Math.abs(a1 - a0) / 0.08));
  for (var i = 0; i <= n; i++) { var t = a0 + (a1 - a0) * i / n, x = cx + Math.cos(t) * r, y = cy + Math.sin(t) * r; if (i === 0) mgraphics.move_to(x, y); else mgraphics.line_to(x, y); }
  mgraphics.stroke();
}
function hit(o) { hits.push(o); }
function button(x, y, w, h, lab, on, kind, name, size) {
  rect(x, y, w, h, on ? C.accent : C.panel, true);
  rect(x, y, w, h, on ? C.accent : C.line, false);
  textC(lab, x + w / 2, y + h / 2 + 3.3, size || 8.5, on ? C.bg : C.ink, true);
  hit({ x: x, y: y, w: w, h: h, kind: kind, name: name });
}

var A0 = Math.PI * 0.75, A1 = Math.PI * 2.25;
function depthOf(n, s) { var q = P[SRC[s].pre + n]; return q ? q.v : 0; }
function knob(cx, cy, r, name) {
  var v = P[name].v, a = A0 + (A1 - A0) * v, act = hover === name || (drag && drag.name === name);
  var rr0 = r * 0.82, lw = Math.max(2.4, r * 0.15);
  KNOB_POS[name] = [cx, cy, r];
  arc(cx, cy, rr0, A0, A1, C.line, lw);
  arc(cx, cy, rr0, A0, a, patchMode ? C.dim : C.accent, lw);
  line(cx, cy, cx + Math.cos(a) * rr0, cy + Math.sin(a) * rr0, C.ink, Math.max(1.5, r * 0.08));
  if (patchMode) {   // the depth of the selected source as an arc from the value (velocity: where soft notes land)
    var dpt = depthOf(name, selSrc);
    if (dpt !== 0) {
      var reach = selSrc === 0 ? -dpt * P.vel_amt.v : Math.abs(dpt) * P.rnd_amt.v * 0.5;
      var b0 = Math.max(0, Math.min(1, v + (selSrc === 0 ? reach : -reach))), b1 = Math.max(0, Math.min(1, v + (selSrc === 0 ? 0 : reach)));
      arc(cx, cy, rr0 + lw + 1.5, A0 + (A1 - A0) * Math.min(b0, b1), A0 + (A1 - A0) * Math.max(b0, b1), SRC[selSrc].col, 2);
    }
  }
  if (act) circle(cx, cy, rr0 + lw + 3.5, patchMode ? SRC[selSrc].col : C.accent, false, 1, 0.5);
  // two small dots: wired to VELOCITY (cyan) / RANDOM (pink)
  for (var s = 0; s < 2; s++) {
    var on = depthOf(name, s) !== 0, dx = cx + r + 2 + s * 6, dy = cy - r;
    if (on) circle(dx, dy, 2.2, SRC[s].col, true); else circle(dx, dy, 2, C.line, false, 1);
  }
  hit({ x: cx - r - 6, y: cy - r - 6, w: 2 * r + 12, h: 2 * r + 12, kind: "knob", name: name });
}
function valueOrDepth(n, cx, y, size) {
  if (patchMode) {
    var d = depthOf(n, selSrc);
    textC(d === 0 ? "-" : sgn(Math.round(d * 100)) + "%", cx, y, size, d === 0 ? C.dim : SRC[selSrc].col, true);
  } else textC(valueText(n), cx, y, size, C.accent, true);
}

// logo: STØMP, the Ø is a kick drum seen from the front (a ring with a beater mark), it thumps on a hit
function drawLogo(x, y) {
  var age = hitT > 0 ? (now() - hitT) / 1000 : 9, k = Math.exp(-age * 9);
  text("ST", x, y, 17, C.ink, true);
  var ox = x + tw("ST", 17, true) + 9, r = 6.6 * (1 + 0.18 * k);
  circle(ox, y - 6, r, C.ink, false, 2.2);
  circle(ox, y - 6, r * 0.42, C.accent, true, 1, 0.35 + 0.65 * k);
  line(ox - r * 1.05, y - 6 + r * 1.05, ox + r * 1.05, y - 6 - r * 1.05, C.ink, 2.2);
  text("MP", ox + 9, y, 17, C.ink, true);
}

function paintLeft() {
  drawLogo(12, 27);
  // preset: < NAME >
  rect(10, 36, 78, 18, C.panel, true); rect(10, 36, 78, 18, C.line, false);
  textC("<", 18, 48.5, 9, C.mid, true); textC(">", 80, 48.5, 9, C.mid, true);
  textC(presetName, 49, 48.5, 8.5, C.ink, true);
  hit({ x: 10, y: 36, w: 18, h: 18, kind: "preset", name: "prev", d: -1 });
  hit({ x: 70, y: 36, w: 18, h: 18, kind: "preset", name: "next", d: 1 });
  // PLAY pad: flashes with every hit (MIDI or the pad)
  var age = hitT > 0 ? (now() - hitT) / 1000 : 9, fl = Math.exp(-age * 7);
  rect(10, 60, 78, 40, C.panel, true);
  rect(10, 60, 78, 40, C.accent, true, 1, 0.12 + 0.75 * fl * (0.4 + 0.6 * lastVel));
  rect(10, 60, 78, 40, C.line, false);
  textC("PLAY", 49, 78, 10, fl > 0.4 ? C.bg : C.ink, true);
  textC(noteName(lastNote) + "  " + fmtHz(fnote(lastNote)), 49, 92, 8, fl > 0.4 ? C.bg : C.mid, true);
  hit({ x: 10, y: 60, w: 78, h: 40, kind: "play", name: "play" });
  button(10, 108, 78, 20, "DICE", false, "dice", "dice");
  text("MIDI: play notes", 10, 146, 7.5, C.mid, false);
  text("the note = the pitch", 10, 157, 7.5, C.mid, false);
}

function paintCol(c) {
  rect(c.x, 6, c.w, 157, C.panel, true);
  var cx = c.x + c.w / 2;
  textC(c.t, cx, 19, 9, C.ink, true);
  // big knob
  knob(cx, 52, 17, c.big);
  textC(label(c.big), cx, 84, 7.5, C.mid, true);
  valueOrDepth(c.big, cx, 96, 8.5);
  // small knobs
  for (var i = 0; i < c.sm.length; i++) {
    var sx = c.sm.length === 1 ? cx : c.x + c.w * (i ? 0.73 : 0.27);
    textC(label(c.sm[i]), sx, 116, 7, C.mid, true);
    knob(sx, 133, 10.5, c.sm[i]);
    valueOrDepth(c.sm[i], sx, 157, 7.5);
  }
}

// the display: the kick as it will sound (waveform, amp envelope, pitch fall) and a playhead on hits
var waveCache = { key: "", cols: null, tmax: 0.5, f0: 0, f1: 0 };
function waveKey() { var s = lastNote + ":"; for (var i = 0; i < SPEC_KNOBS.length; i++) s += P[SPEC_KNOBS[i].n].v + ","; return s; }
function computeWave() {
  var key = waveKey(); if (key === waveCache.key) return waveCache;
  var alen = M.alen(P.amp_len.v) + M.aatt(P.amp_att.v), tmax = Math.max(0.08, alen * 1.08), sr = 6000, n = Math.ceil(tmax * sr);
  var cols = [], wpx = DW - 16, ph = 0, pm = 0, fmr = M.fmr(P.fm_rat.v), fi = 6 * P.fm_amt.v * P.fm_amt.v, fd = M.fdec(P.fm_dec.v);
  for (var c = 0; c < wpx; c++) cols.push([0, 0]);
  for (var i = 0; i < n; i++) {
    var t = i / sr, m = model(t, lastNote);
    ph += Math.min(m.f, 2900) / sr; pm += Math.min(m.f * fmr, 2900) / sr;
    var y = Math.sin(2 * Math.PI * ph + fi * Math.exp(-t / fd) * Math.sin(2 * Math.PI * pm)) * m.env;
    var g = Math.pow(2, P.dr_amt.v * 5), dm = Math.min(1, P.dr_amt.v * 5);
    y = y + (tanh(g * y) / tanh(g) - y) * dm;
    var cc = Math.min(wpx - 1, Math.floor(t / tmax * wpx));
    if (y < cols[cc][0]) cols[cc][0] = y; if (y > cols[cc][1]) cols[cc][1] = y;
  }
  waveCache = { key: key, cols: cols, tmax: tmax, f0: model(0, lastNote).f, f1: fnote(lastNote) };
  return waveCache;
}
function paintDisplay() {
  rect(DX, DY, DW, DH, C.screen, true);
  rect(DX, DY, DW, DH, C.line, false);
  if (patchMode) { paintPatchHelp(); return; }
  var w = computeWave(), x0 = DX + 8, wpx = DW - 16, top = DY + 22, h = DH - 44, mid = top + h / 2, i;
  // grid
  line(x0, mid, x0 + wpx, mid, C.line, 1, 0.6);
  // waveform (min/max per pixel)
  for (i = 0; i < w.cols.length; i++) line(x0 + i + 0.5, mid - w.cols[i][1] * h / 2, x0 + i + 0.5, mid - w.cols[i][0] * h / 2 + 0.01, C.mid, 1, 0.75);
  // amp envelope (cyan) and pitch (pink, log scale between the end and the start frequency)
  var lf0 = Math.log(w.f0), lf1 = Math.log(w.f1), steps = 90, px, py;
  col(C.accent); mgraphics.set_line_width(1.6);
  for (i = 0; i <= steps; i++) {
    var t = i / steps * w.tmax, e = model(t, lastNote).env;
    px = x0 + i / steps * wpx; py = mid - e * h / 2;
    if (i === 0) mgraphics.move_to(px, py); else mgraphics.line_to(px, py);
  }
  mgraphics.stroke();
  col(C.pink); mgraphics.set_line_width(1.6);
  for (i = 0; i <= steps; i++) {
    var tt = i / steps * w.tmax, f = model(tt, lastNote).f, k = lf0 > lf1 + 1e-6 ? (Math.log(f) - lf1) / (lf0 - lf1) : 0;
    px = x0 + i / steps * wpx; py = top + h - k * h;
    if (i === 0) mgraphics.move_to(px, py); else mgraphics.line_to(px, py);
  }
  mgraphics.stroke();
  // labels
  text(fmtHz(w.f0), x0, DY + 15, 8.5, C.pink, true);
  textR("LENGTH " + fmtMs(M.alen(P.amp_len.v) + M.aatt(P.amp_att.v)), DX + DW - 8, DY + 15, 8, C.mid, true);
  text(noteName(lastNote), x0, DY + DH - 8, 8.5, C.ink, true);
  textR(fmtHz(w.f1), DX + DW - 8, DY + DH - 8, 8.5, C.pink, true);
  // playhead
  if (hitT > 0) {
    var age = (now() - hitT) / 1000;
    if (age < w.tmax) { px = x0 + age / w.tmax * wpx; line(px, top - 4, px, top + h + 4, C.pink, 1.2, 0.9); }
  }
}
function paintPatchHelp() {
  var x = DX + 10, y = DY + 18, s = SRC[selSrc];
  text("PATCH MODE  -  " + s.lab, x, y, 9, s.col, true);
  var L = ["click VEL or RND on the right = the source",
    "click a knob = wire it to the source",
    "drag up / down on a knob = depth (+ / -)",
    "double-click a knob = cut its cable",
    "VEL: soft notes move the knob by the depth",
    "RND: every hit lands somewhere new",
    "click here or PATCH = back to the knobs"];
  for (var i = 0; i < L.length; i++) text(L[i], x, y + 17 + i * 13.5, 7.8, C.ink, false);
  button(DX + DW - 70, DY + DH - 22, 62, 16, "CLEAR " + s.short, false, "clear", "clear", 7.5);
  hit({ x: DX, y: DY, w: DW, h: DH - 26, kind: "void", name: "void" });
}

function paintSources() {
  rect(SX - 4, 6, 66, 157, C.panel, true);
  for (var s = 0; s < 2; s++) {
    var y = 22 + s * 42, src = SRC[s], sel = patchMode && selSrc === s;
    circle(SX + 6, y - 3, 5, src.col, true);
    if (sel) circle(SX + 6, y - 3, 8, src.col, false, 1.2);
    text(src.short, SX + 15, y, 8.5, C.ink, true);
    hit({ x: SX - 2, y: y - 12, w: 56, h: 16, kind: "src", name: "src" + s, src: s });
    // global amount: drag
    var n = src.amt;
    textC(pct(P[n].v), SX + 26, y + 16, 9, src.col, true);
    hit({ x: SX - 2, y: y + 5, w: 56, h: 15, kind: "amount", name: n });
    if (hover === n || (drag && drag.name === n)) rect(SX - 2, y + 5, 56, 15, src.col, false, 1, 0.5);
  }
  button(SX, 106, 52, 18, "PATCH", patchMode, "patch", "patch");
  // output meter
  var db = function (v) { var d = 20 * Math.log(Math.max(v, 1e-6)) / Math.LN10; return Math.max(0, Math.min(1, (d + 48) / 48)); };
  var ls = [levL, levR];
  for (var c = 0; c < 2; c++) {
    var mx = SX + c * 5 + 20, f = db(ls[c]), my = 132, mh = 26;
    rect(mx, my, 3, mh, C.line, true);
    rect(mx, my + mh * (1 - f), 3, mh * f, ls[c] > 0.98 ? C.pink : C.accent, true);
  }
}

// cables (patch mode): from the selected source to every knob it reaches
function cable(x1, y1, x2, y2, c, a) {
  col(c, a); mgraphics.set_line_width(1.8);
  var sag = 18 + Math.abs(x2 - x1) * 0.12;
  mgraphics.move_to(x1, y1); mgraphics.curve_to(x1 - 30, Math.min(y1 + sag, H0 - 6), x2 + 20, Math.min(y2 + sag, H0 - 6), x2, y2); mgraphics.stroke();   // stays inside the panel
}
function paintCables() {
  if (!patchMode) return;
  // every cable of both sources: the selected one bright, the other one faint
  for (var k = 0; k < 2; k++) {
    var si = k === 0 ? 1 - selSrc : selSrc, src = SRC[si], sy = 22 + si * 42 - 3, a = si === selSrc ? 0.8 : 0.22;
    for (var n in KNOB_POS) {
      if (depthOf(n, si) === 0) continue;
      var kp = KNOB_POS[n];
      cable(SX + 6, sy, kp[0], kp[1] + kp[2] * 0.5, src.col, a);
      circle(kp[0], kp[1] + kp[2] * 0.5, 2.5, src.col, true, 1, a + 0.2);
    }
  }
}

function paint() {
  var sz = mgraphics.size;
  scaleF = Math.min(sz[0] / W0, sz[1] / H0); if (!(scaleF > 0)) scaleF = 1;
  mgraphics.scale(scaleF, scaleF);
  hits = []; KNOB_POS = {};
  rect(0, 0, W0, H0, C.bg, true);
  if (patchMode) hit({ x: 0, y: 0, w: W0, h: H0, kind: "void", name: "void" });   // click outside = back
  // each part on its own: an error in one part must not leave the rest of the panel blank
  safe(paintLeft);
  for (var i = 0; i < COLS.length; i++) safe(paintCol, COLS[i]);
  safe(paintDisplay);
  safe(paintSources);
  safe(paintCables);
}
var reported = {};
function safe(fn, arg) {
  try { fn(arg); } catch (e) {
    var msg = "STOMP panel: " + (fn.name || "part") + ": " + e;
    if (!reported[msg]) { reported[msg] = 1; if (typeof post === "function") post(msg + "\n"); }
    lastError = msg;
  }
}
var lastError = "";

// ---------- mouse ----------
function find(x, y) { for (var i = hits.length - 1; i >= 0; i--) { var h = hits[i]; if (x >= h.x && x <= h.x + h.w && y >= h.y && y <= h.y + h.h) return h; } return null; }
function onclick(x, y, but, cmd, shift) {
  x /= scaleF; y /= scaleF;
  var h = find(x, y); if (!h) return;
  if (h.kind === "knob") {
    if (patchMode) {
      var dn = SRC[selSrc].pre + h.name;
      if (P[dn].v === 0) send(dn, 0.5);
      drag = { kind: "depth", name: dn, y0: y, n0: P[dn].v === 0 ? 0.5 : P[dn].v };
    } else drag = { kind: "knob", name: h.name, y0: y, n0: P[h.name].v };
  }
  else if (h.kind === "amount") drag = { kind: "knob", name: h.name, y0: y, n0: P[h.name].v };
  else if (h.kind === "src") { if (patchMode && selSrc === h.src) patchMode = false; else { selSrc = h.src; patchMode = true; } }
  else if (h.kind === "patch") patchMode = !patchMode;
  else if (h.kind === "void") patchMode = false;
  else if (h.kind === "clear") { for (var i = 0; i < SPEC_KNOBS.length; i++) send(SRC[selSrc].pre + SPEC_KNOBS[i].n, 0); }
  else if (h.kind === "play") play();
  else if (h.kind === "dice") dice();
  else if (h.kind === "preset") loadPreset(preset + h.d);
  dirty = true;
}
function ondrag(x, y, but, cmd, shift) {
  if (!drag) return;
  x /= scaleF; y /= scaleF;
  var k = shift ? 0.0007 : 0.007;
  if (drag.kind === "knob") send(drag.name, Math.round(Math.max(0, Math.min(1, drag.n0 + (drag.y0 - y) * k)) * 1000) / 1000);
  if (drag.kind === "depth") send(drag.name, Math.round(Math.max(-1, Math.min(1, drag.n0 + (drag.y0 - y) * k * 2)) * 1000) / 1000);
  if (!but) { drag = null; dirty = true; }
}
function ondblclick(x, y) {
  x /= scaleF; y /= scaleF;
  var h = find(x, y); if (!h) return;
  if (h.kind === "knob") { if (patchMode) send(SRC[selSrc].pre + h.name, 0); else send(h.name, P[h.name].d); }
  if (h.kind === "amount") send(h.name, P[h.name].d);
  drag = null;
}
function onidle(x, y) { var h = find(x / scaleF, y / scaleF), k = h ? h.name : null; if (k !== hover) { hover = k; dirty = true; } }
function onidleout() { if (hover) { hover = null; dirty = true; } }
function onresize() { dirty = true; }
